INSERT INTO `articles` VALUES (1,4,1,'来到澳门体验','',NULL,'不错啊',NULL,NULL,'published',0,0,0,NULL,'2025-09-07 03:40:49','2025-09-07 03:40:49','2025-09-07 03:40:49'),(5,4,1,'澳门大三巴牌坊游览攻略，必看的历史遗迹','article-1-1757246519',NULL,'<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>澳门女「赌神」：跟我混，百万不算富，千万刚起步</title>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n            line-height: 1.6;\n            max-width: 800px;\n            margin: 0 auto;\n            padding: 20px;\n            color: #333;\n        }\n        .article-meta {\n            border-bottom: 1px solid #eee;\n            padding-bottom: 20px;\n            margin-bottom: 30px;\n        }\n        .article-title {\n            font-size: 24px;\n            font-weight: bold;\n            margin-bottom: 10px;\n        }\n        .article-author {\n            color: #666;\n            font-size: 14px;\n        }\n        .rich_media_content {\n            font-size: 16px;\n            line-height: 1.8;\n        }\n        .rich_media_content img {\n            max-width: 100%;\n            height: auto;\n            display: block;\n            margin: 20px auto;\n        }\n        .rich_media_content p {\n            margin-bottom: 16px;\n        }\n    </style>\n</head>\n<body>\n    <div class=\"article-meta\">\n        <div class=\"article-title\">澳门女「赌神」：跟我混，百万不算富，千万刚起步</div>\n        \n        \n    </div>\n    <div class=\"rich_media_content js_underline_content defaultNoSetting\" id=\"js_content\" style=\"-webkit-\"><p><span style=\"background-color: transparent;color: rgb(171, 25, 66);font-weight: 700;letter-spacing: 0.5px;text-align: left;caret-color: var(--weui-BRAND)\">澳门合集第240篇（240/999）</span></p><section style=\"-webkit-tap-highlight-color: transparent;margin: 0px 8px;padding: 0px;outline: 0px;max-width: 100%;box-sizing: border-box !important;overflow-wrap: break-word !important;color: rgb(0, 0, 0);font-family: -apple-system, BlinkMacSystemFont,\"Helvetica Neue\", \"PingFang SC\", \"Hiragino Sans GB\", \"Microsoft YaHei UI\", \"Microsoft YaHei\", Arial, sans-serif;font-size: 17px;font-style: normal;font-variant-ligatures: normal;font-variant-caps: normal;font-weight: 400;letter-spacing: 0.544px;orphans: 2;text-indent: 0px;text-transform: none;white-space: normal;widows: 2;word-spacing: 0px;-webkit-text-stroke-width: 0px;caret-color: rgb(7, 193, 96);text-decoration-thickness: initial;text-decoration-style: initial;text-decoration-color: initial;text-align: left;background-color: rgb(255, 255, 255);visibility: visible;line-height: 1.5em;\'><span style=\"-webkit-tap-highlight-color: transparent;margin: 0px;padding: 0px;outline: 0px;max-width: 100%;box-sizing: border-box !important;overflow-wrap: break-word !important;color: rgb(171, 25, 66);font-weight: 700;letter-spacing: 0.5px;font-size: 17px;visibility: visible\"><br style=\"-webkit-tap-highlight-color: transparent;margin: 0px;padding: 0px;outline: 0px;max-width: 100%;box-sizing: border-box !important;overflow-wrap: break-word !important;visibility: visible\"/></span></section><p style=\"-webkit-tap-highlight-color: transparent;margin: 0px;padding: 0px;outline: 0px;max-width: 100%;box-sizing: border-box !important;overflow-wrap: break-word !important;clear: both;min-height: 1em;color: rgb(51, 51, 51);font-family: -apple-system, BlinkMacSystemFont,\"Helvetica Neue\", \"PingFang SC\", \"Hiragino Sans GB\", \"Microsoft YaHei UI\", \"Microsoft YaHei\", Arial, sans-serif;font-size: 17px;font-style: normal;font-variant-ligatures: normal;font-variant-caps: normal;font-weight: 400;letter-spacing: 0.544px;orphans: 2;text-align: justify;text-indent: 0px;text-transform: none;white-space: normal;widows: 2;word-spacing: 0px;-webkit-text-stroke-width: 0px;caret-color: rgb(7, 193, 96);text-decoration-thickness: initial;text-decoration-style: initial;text-decoration-color: initial;background-color: rgb(255, 255, 255);visibility: visible;\'><strong style=\"-webkit-tap-highlight-color: transparent;margin: 0px;padding: 0px;outline: 0px;max-width: 100%;box-sizing: border-box !important;overflow-wrap: break-word !important;font-style: normal;font-variant-ligatures: normal;font-variant-caps: normal;letter-spacing: 0.544px;orphans: 2;text-align: justify;text-indent: 0px;text-transform: none;white-space: normal;widows: 2;word-spacing: 0px;-webkit-text-stroke-width: 0px;caret-color: rgb(7, 193, 96);background-color: rgb(255, 255, 255);text-decoration-thickness: initial;text-decoration-style: initial;text-decoration-color: initial;color: rgb(102, 102, 102);font-family: Arial, Helvetica, sans-serif;font-size: 14px;line-height: 24px;visibility: visible\"><span style=\"-webkit-tap-highlight-color: transparent;margin: 0px 8px 0px 0px;padding: 4px 10px;outline: 0px;max-width: 100%;box-sizing: border-box !important;overflow-wrap: break-word !important;color: rgb(255, 255, 255);border-radius: 5px;background-color: rgb(171, 219, 171);visibility: visible\">公众号</span></strong><span style=\"-webkit-tap-highlight-color: transparent;margin: 0px;padding: 0px;outline: 0px;max-width: 100%;box-sizing: border-box !important;overflow-wrap: break-word !important;font-style: normal;font-variant-ligatures: normal;font-variant-caps: normal;font-weight: 400;letter-spacing: 0.544px;orphans: 2;text-align: justify;text-indent: 0px;text-transform: none;white-space: normal;widows: 2;word-spacing: 0px;-webkit-text-stroke-width: 0px;caret-color: rgb(7, 193, 96);background-color: rgb(255, 255, 255);text-decoration-thickness: initial;text-decoration-style: initial;text-decoration-color: initial;font-family: Arial, Helvetica, sans-serif;font-size: 14px;line-height: 24px;color: rgb(127, 127, 127);visibility: visible\"><strong style=\"-webkit-tap-highlight-color: transparent;margin: 0px;padding: 0px;outline: 0px;max-width: 100%;box-sizing: border-box !important;overflow-wrap: break-word !important;visibility: visible\">秋淑曼 出品</strong></span></p><p style=\"-webkit-tap-highlight-color: transparent;margin: 0px;padding: 0px;outline: 0px;max-width: 100%;box-sizing: border-box !important;overflow-wrap: break-word !important;clear: both;min-height: 1em;text-align: left;font-weight: 400;color: var(--weui-FG-HALF);font-size: var(--articleFontsize);visibility: visible\"><span style=\"-webkit-tap-highlight-color: transparent;margin: 0px;padding: 0px;outline: 0px;max-width: 100%;box-sizing: border-box !important;overflow-wrap: break-word !important;background-color: transparent;caret-color: var(--weui-BRAND);letter-spacing: 0.034em;font-size: 12px;font-weight: bold\"><br/></span></p><p style=\"text-align: left;-webkit-tap-highlight-color: transparent;margin: 0px;padding: 0px;outline: 0px;max-width: 100%;clear: both;min-height: 1em;font-weight: 400;color: var(--weui-FG-HALF);font-size: var(--articleFontsize);visibility: visible;box-sizing: border-box !important;overflow-wrap: break-word !important\"><span style=\"background-color: transparent;color: var(--weui-FG-HALF);font-size: 12px;font-weight: bold;letter-spacing: 0.034em;text-align: justify;caret-color: var(--weui-BRAND)\">口述｜邓飞龙</span></p><p style=\"text-align: justify;-webkit-tap-highlight-color: transparent;margin: 0px;padding: 0px;outline: 0px;max-width: 100%;clear: both;min-height: 1em;font-weight: 400;color: var(--weui-FG-HALF);font-size: var(--articleFontsize);visibility: visible;box-sizing: border-box !important;overflow-wrap: break-word !important\"><span style=\"background-color: transparent;font-size: 12px;font-weight: bold;letter-spacing: 0.034em;caret-color: var(--weui-BRAND);color: var(--weui-FG-HALF);text-align: left\">编辑｜茹曼怡</span></p><p style=\"-webkit-tap-highlight-color: transparent;margin: 0px;padding: 0px;outline: 0px;max-width: 100%;box-sizing: border-box !important;overflow-wrap: break-word !important;clear: both;min-height: 1em;font-weight: 400;color: var(--weui-FG-HALF);font-size: var(--articleFontsize);text-align: center;visibility: visible\"><span style=\"-webkit-tap-highlight-color: transparent;margin: 0px;padding: 0px;outline: 0px;max-width: 100%;box-sizing: border-box !important;overflow-wrap: break-word !important;background-color: transparent;color: rgb(171, 25, 66);font-weight: 700;letter-spacing: 0.5px;text-align: left;caret-color: var(--weui-BRAND)\"><span style=\"background-color: transparent;font-size: var(--articleFontsize);caret-color: var(--weui-BRAND)\"><br/></span></span></p><p style=\"-webkit-tap-highlight-color: transparent;margin: 0px;padding: 0px;outline: 0px;max-width: 100%;box-sizing: border-box !important;overflow-wrap: break-word !important;clear: both;min-height: 1em;font-weight: 400;color: var(--weui-FG-HALF);font-size: var(--articleFontsize);text-align: center;visibility: visible\"><span style=\"-webkit-tap-highlight-color: transparent;margin: 0px;padding: 0px;outline: 0px;max-width: 100%;box-sizing: border-box !important;overflow-wrap: break-word !important;background-color: transparent;color: rgb(171, 25, 66);font-weight: 700;letter-spacing: 0.5px;text-align: left;caret-color: var(--weui-BRAND)\"><span style=\"background-color: transparent;font-size: var(--articleFontsize);caret-color: var(--weui-BRAND)\"><span class=\"wx_text_underline\">01</span></span></span></p><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\"><span style=\"color: rgb(47, 118, 195);font-weight: bold\">妈阁引路人</span></section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">那年春天，是动物交配的季节。</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">公司美女经理兰姐点名让我陪她去澳门出差，我也好奇，赌场里究竟是个什么样的。</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">早上8点，深圳蛇口码头的晨雾还未散去，我和兰姐登上前往澳门氹仔码头的邮轮。</span></section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">海浪有节奏的拍打着船舷，航行一个小时后，兰姐兴奋地指向窗外：</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">「快看！那里就是澳门！」</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">很快，氹仔客运码头就映入眼帘。</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">兰姐是澳门通，<span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">下了邮轮，她熟门熟路带着我钻进一辆标着「澳门威尼斯人」的发财巴士。</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">发财车摇摇晃晃地载着我们前往赌场，下车瞬间，看着眼前的豪华建筑群，我恍如隔世，这哪是赌场？分明就是宫殿！</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">走进金碧辉煌的威尼斯人，兰姐竟一溜烟地消失了！</span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\"><br/></span><section><section style=\"display: inline-block\"><img data-ratio=\"1\" data-src=\"https://mmbiz.qpic.cn/mmbiz_jpg/enu35DRIiaThKBA48qShtoGEmZrXBw0IXqSaibhSkd3ZwR8e5Tw5APIMfCgBQibmCRicl9unRL72VwVOeibzw8DBbrw/640?wx_fmt=jpeg\" data-type=\"jpg\" data-w=\"1080\" style=\"height: auto !important\"/></section></section><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\"></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">我在中场里晃荡，一台台老虎机的屏幕泛着幽蓝，轮盘的象牙球滚动时发出清脆的叮咚声，一切都很魔幻。</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">逛</span><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">了一大圈，我终于在一张败家乐赌台发现了兰姐的身影。</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">兰姐坐在赌台前，也发现了身后的我，我刚想开口，她就抢先一步，压低声音说道：</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">「你先听我说，别靠我太近，看着就行，别和我搭话，赢了我请吃饭」</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">我小鸡啄米般点点头。</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">荷官示意下注，疑惑的是兰姐的目光盯的不是路单屏幕，而是坐在5号位的胖子赌客。</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">那胖子头发冒油，印堂发黑，犹豫两秒后，把1万码压在了庄上。</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\">兰姐看准时机，把1万码压在闲上，胖子愣了一下，瞥了眼兰姐。</span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.578px;caret-color: var(--weui-BRAND)\">买定离手，荷官把庄闲两家牌分别推到胖子和兰姐面前，兰姐看都不看，直接翻开，2+5，闲7点。</span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\">「7点！赢定啦！」</span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">兰姐朝着胖子喊，言语中带着挑衅。</span></section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">胖子也不甘示弱，回怼兰姐：</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">「7点很大吗？有8点的嘛！」</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">胖子随手翻出一张Q，正想翻开第二张之际，兰姐对着那张庄牌喊：</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">「公！公！公！」</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">胖子咬牙切齿，捻着手中的纸牌大声喊：</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">「三边！三边！三边！」</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">牌开了，一张K！胖子还要博一张牌。</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">「庄博」</span></section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\">荷官把一张补牌推到胖子面前。</span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\">胖子掀开一侧，是张四边牌，他歇斯底里地喊：</span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\">「吹！吹！吹啊！」</span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\">兰姐索性站了起来，双手激动的拍打着赌台绒布：</span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\">「杀！杀！杀！」</span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\">牌开了，一张10，庄0点，</span><span style=\"background-color: transparent;letter-spacing: 0.578px;caret-color: var(--weui-BRAND)\">胖子输了。</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">胖子怒不可遏，颤抖的手握着最后2万筹码，全部梭哈到闲上。</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">兰姐见状，把2万压在庄上。</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\">胖子立马回撤筹码，又压在庄上。</span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\">兰姐也收回筹码，压在闲上。</span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\">「臭X，你他妈德！想干什么啊？」</span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\">胖子终于是对着兰姐爆了一句国粹。</span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\">兰姐也不示弱，转过头对身后的赌客说道：</span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\">「喂，有灯不跟，输到卖身啊！」</span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\">话毕，所有围台的老哥纷纷把注码压在了胖子的对家。</span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\">此时的我也想参与，但摸着自己口袋的300港币，连上台的资格都没有。</span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\">也罢，观摩他们对赌可比自己下场要刺激多了。</span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\">众人买定后，荷官开始派牌。</span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\">兰姐还是非常淡定，直接把两张闲牌翻开，A+8，9点！</span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\">「耶！一枪过！」</span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\"><br/></span></section><section style=\"margin-bottom: 0px\">胖子看着欢呼的众人，生无可恋翻开第一张庄牌，一张4，随后又像抓住救命稻草，捻着第二张牌：</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">「两边！两边！」</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">兰姐带领众人齐声喊：</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">「剪！剪他的边！」</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">果然是张两边牌，胖子对着牌喊：</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">「顶！顶！顶！」</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">兰姐更是直接凑近胖子的耳边：</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">「吹！吹！吹！」</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">那唾沫星子都溅到了胖子的脸上。</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">胖子最后用尽全力把那张牌甩在赌台的绒布上，还是一张4！</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">「8输9，经常有哈！」</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">在众人的笑声中，胖子瘫坐在椅子上，面无表情地看着天花板，随后又恶狠狠地瞪向兰姐。</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">兰姐收好筹码，拉着我的胳膊：</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">「飞龙，我们赶紧走！」</section><section style=\"margin-bottom: 0px\"><br/><section style=\"text-align: center\"><section style=\"display: inline-block\"></section><span style=\"background-color: transparent;font-size: var(--articleFontsize);caret-color: var(--weui-BRAND);color: rgb(171, 25, 66);font-weight: 700;letter-spacing: 0.5px;text-align: left\">02</span></section></section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\"><span style=\"font-weight: bold;color: rgb(47, 118, 195)\">澳门女「赌神」</span></section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">我还没问去哪，兰姐就一路把我拉到了购物中心——四季名店，<span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">走进一家超大的LV，各种奢侈品琳琅满目。</span></section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">「好看吗？」</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">镜子里，兰姐把包包试挎在右手手腕，左手拨动着发丝，随口问我。</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">看着镜子里风韵犹存的兰姐，我说，<span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">兰姐你可真好看！</span></section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">「我说这个包！你想哪去啦？」</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">兰姐俏皮地嘟了嘟嘴。</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">我才回过神来，看了眼价格，2万8千多，这么贵！</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">「不止，这款还要配货，没有小4万拿不下来」</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">兰姐有些不舍的把包包放回原处，又拉着我返回赌场，说得找庄家报销。</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">我们走进高额区，一张赌台传来潮水般的欢呼声，兰姐快步走了过去。</section><section style=\"margin-bottom: 0px\"><br/><section><section style=\"display: inline-block\"><img data-ratio=\"1\" data-src=\"https://mmbiz.qpic.cn/mmbiz_jpg/enu35DRIiaTiaI3rIx4UmL0m8GkMRpD5nwIf73IVQiaJE0xVfIyMIlcicT2PH3QJlReDVqcwNpGut7NPkpsIlcac9g/640?wx_fmt=jpeg\" data-type=\"jpg\" data-w=\"1080\" style=\"height: auto !important\"/></section></section></section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">听围观的赌客兴奋说，一位大哥手气很好，赢了几口，大概有80万，兰姐不禁向那位大哥投去羡慕的眼神。</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">兰姐拉低了衣领，露出傲人的大杀器，在大哥身旁坐下，跟大哥搭讪：</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">「哥，你手气这么好，带带妹妹呗！」</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">赌钱的人大多不喜欢带别人，怕搭沉船，影响自己的运气，但<span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">大哥看着楚楚可怜的兰姐，不让她跟注，倒显得不解风情：</span></section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">「美女啊，你相信哥的话，今天就跟着哥发财！」</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">「谢谢哥！哥肯定发大财！」</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">兰姐谄媚地笑了笑，与之前对待胖子的态度发生了180度的旋转。</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">说时迟那时快，大哥下注10万压闲，看了兰姐一眼，兰姐也跟注1万。</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">荷官发牌，大哥眯牌，2+3，闲5点。</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">庄K+2，2点，根据规则，两家都要补牌。</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">大哥眯着闲补，兰姐就在一旁喊：</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">「两边！两边！」</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">扑克牌掀开一侧，是三边，大哥呼出一口浊气，有些失望，兰姐随即安慰道：</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">「没事哥，3点照样赢他」</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">「顶！顶！顶！」</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">可当闲补翻开时，却是一张7，闲2点，这把牌相当悬。</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">紧接着兰姐朝庄补卖力喊：</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">「四边！四边！」</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">庄补开了，一张肥婆8，庄0点，闲2点，闲赢！</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">大哥与兰姐一番欢呼雀跃后，随手打赏了兰姐5000茶钱：</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">「不错喔美女，跟我合财，再玩几把呗！」</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">兰姐接过小费，站起身来：</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">「谢谢哥，我就不玩了哈」</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">离开高额区，我纳闷兰姐怎么不乘胜追击？</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">「刚才那一把已经很悬了，要是大哥下一把输了，肯定会怪我的」</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">兰姐说在赌场里，要懂得见好就收。</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">在账房，兰姐把赢来的筹码换成了港币，港币又换成了LV牛皮包，人也开始飘了，她拉着我的手：</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">「小龙，跟我混澳门，百万不算富，千万刚起步！哈哈哈！」</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\">俨然一副澳门女赌神的姿态。</section><section style=\"margin-bottom: 0px\"><br/></section><section style=\"margin-bottom: 0px\"></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\">到了晚上，为了省钱，我和兰姐共处一间房，她睡房间，我睡客厅。</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.034em;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"letter-spacing: 0.578px\">我看着窗外的澳门夜景，霓虹灯将整个赌城照耀得如玉皇大帝的天宫，</span><span style=\"background-color: transparent;letter-spacing: 0.578px;caret-color: var(--weui-BRAND)\">一种寂寞感莫名袭来，翻来覆去睡不着。</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.578px;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.578px;caret-color: var(--weui-BRAND)\">让我意外的是，兰姐睡觉居然没关门，我试探性喊了一声：</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.578px;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.578px;caret-color: var(--weui-BRAND)\">「兰姐，客厅好像有蚊子……」</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.578px;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.578px;caret-color: var(--weui-BRAND)\">「啊？房间里没有耶，要不……你进来睡？」</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.578px;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.578px;caret-color: var(--weui-BRAND)\">我内心挣扎着，见我迟迟没有动静，兰姐又催促：</span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.578px;caret-color: var(--weui-BRAND)\"><br/></span></section><section style=\"margin-bottom: 0px\"><span style=\"background-color: transparent;letter-spacing: 0.578px;caret-color: var(--weui-BRAND)\">「进不进来？不进来活该你让蚊子咬！」</span></section><p class=\"js_pay_preview_filter\"><mp-pay-preview-filter data-offset=\"184\"></mp-pay-preview-filter></p></div>\n</body>\n</html>',NULL,NULL,'published',0,153,24,'[\"景点\", \"攻略\", \"文化\", \"观光\"]','2025-09-04 04:01:59','2025-09-07 04:01:59','2026-07-31 22:37:25'),(6,4,1,'漫步澳门历史城区，感受东西方文化交融','article-2-1757246519',NULL,'<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <meta name=\"referrer\" content=\"no-referrer\">\n    <title>澳门女「赌神」：跟我混，百万不算富，千万刚起步</title>\n    <style>\n        body {\n            font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n            line-height: 1.6;\n            max-width: 800px;\n            mar