  `created_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `content_text` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '纯文本内容',
  `content_html` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'HTML格式内容（包含图片）',
  `completed` tinyint DEFAULT '0',
  `retry_count` int DEFAULT '0' COMMENT '重试次数',
  `last_attempt` datetime DEFAULT NULL COMMENT '最后尝试时间',
  `error_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '错误信息',
  `updated_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_title` (`title`(100)) USING BTREE,
  KEY `idx_url` (`url`(100)) USING BTREE,
  KEY `idx_time` (`created_time`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
